function videoErrorMessage(error){const raw=error?.errorMsg||error?.message||(typeof error==='string'?error:'The video connection could not start.');if(raw.includes('account-missing-payment-method'))return 'Daily is blocking this call because the host account needs a payment method. The host must review Billing in the Daily dashboard before anyone can join. Your invitation link is still valid.';return raw}
const joinFeedback=document.createElement('p');joinFeedback.id='joinStatus';joinFeedback.className='device-feedback';joinFeedback.setAttribute('role','alert');$('joinForm').insertBefore(joinFeedback,$('joinForm').querySelector('[type=submit]'));
let liveCall=null;const meetingId=new URLSearchParams(location.search).get('meeting');let hostKey=new URLSearchParams(location.hash.slice(1)).get('host')||'';if(hostKey)history.replaceState(null,'',location.pathname+location.search);
const launch=document.createElement('button');launch.className='host-launch';launch.textContent='Create meeting';document.querySelector('header').append(launch);
const dialog=document.createElement('dialog');dialog.id='createMeeting';dialog.innerHTML=`<form method="dialog"><div class="panel-title"><h2>Invite your sisterhood</h2><button aria-label="Close meeting creation">×</button></div></form><p class="fine">Invite members with a link. Keep your host link private.</p><form id="createMeetingForm"><label>Meeting title<input id="meetingTitle" value="Beautifully Flourish Book Club" required maxlength="100"></label><label>Date and time<input id="meetingDate" type="datetime-local" required></label><p id="meetingTimezone" class="fine"></p><label class="recurring-label"><input type="checkbox" id="meetingRecurring" checked> Recurring weekly · Reuse this room and invitation</label><label>Host password<input id="hostPassword" type="password" autocomplete="current-password" required><small>The private host password configured on your server.</small></label><button class="primary" id="createMeetingSubmit">Create invitation</button></form><p id="meetingSetupStatus" class="device-feedback" role="status"></p><section id="invitationResult" hidden><label>Member invitation<textarea id="inviteText" readonly rows="8"></textarea></label><button class="device-action" id="copyInvite">Copy invitation</button><label>Your private host link<input id="hostLink" readonly></label><button class="device-action" id="copyHost">Copy host link</button><p class="fine">Save both now. The private host link is shown only when created. Send members only the member invitation.</p></section>`;document.body.append(dialog);
async function api(url,body){let response;try{response=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined})}catch{throw Error('Bloom’s meeting server is unreachable. Check that it is running.')}let data;try{data=await response.json()}catch{throw Error('This server serves the prototype only. Start Bloom with node server.mjs to use meeting creation.')}if(!response.ok)throw Error(data.error||'Request failed.');return data}
launch.onclick=async()=>{dialog.showModal();$('meetingTimezone').textContent='Time zone: '+Intl.DateTimeFormat().resolvedOptions().timeZone;try{const config=await api('/api/config');$('meetingSetupStatus').textContent=config.ready?'Ready to create a live meeting.':'Setup needed: connect Daily, set your private host password, and configure a public HTTPS Bloom address. Invitation creation stays unavailable until then.';$('createMeetingSubmit').disabled=!config.ready}catch(e){$('meetingSetupStatus').textContent=e.message;$('createMeetingSubmit').disabled=true}};
$('createMeetingForm').onsubmit=async e=>{e.preventDefault();$('createMeetingSubmit').disabled=true;$('meetingSetupStatus').textContent='Creating your gathering…';try{const meeting=await api('/api/meetings',{title:$('meetingTitle').value,date:new Date($('meetingDate').value).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,recurring:$('meetingRecurring').checked,hostPassword:$('hostPassword').value});$('hostPassword').value='';$('inviteText').value=`You’re invited to ${meeting.title}!\n\n${new Date(meeting.date).toLocaleString(undefined,{dateStyle:'full',timeStyle:'short',timeZone:meeting.timezone})} (${meeting.timezone})${meeting.recurring?'\nWeekly gathering · Use this same link each week.':''}\n\nJoin Bloom: ${meeting.inviteUrl}\n\nCheck your camera and audio, then wait for your host to welcome you in.`;$('hostLink').value=meeting.hostUrl;$('invitationResult').hidden=false;$('meetingSetupStatus').textContent='Your invitation is ready. Copy the member invitation to share.'}catch(error){$('meetingSetupStatus').textContent=error.message}finally{$('createMeetingSubmit').disabled=false}};
async function copy(id){try{await navigator.clipboard.writeText($(id).value);$('meetingSetupStatus').textContent='Copied.'}catch{$(id).focus();$(id).select();$('meetingSetupStatus').textContent='Copy the selected text with Ctrl+C.'}}$('copyInvite').onclick=()=>copy('inviteText');$('copyHost').onclick=()=>copy('hostLink');
let dailyLoadPromise=null;
function dailySdk(){return window.Daily||window.DailyIframe}
async function loadDaily(){
 if(typeof dailySdk()?.createFrame==='function')return dailySdk();
 if(!dailyLoadPromise)dailyLoadPromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');
  const timeout=setTimeout(()=>{script.remove();dailyLoadPromise=null;reject(Error('The video service took too long to load. Please try joining again.'))},20000);
  script.src='https://unpkg.com/@daily-co/daily-js@0.94.0/dist/daily.js';
  script.onload=()=>{clearTimeout(timeout);const sdk=dailySdk();if(typeof sdk?.createFrame==='function')resolve(sdk);else{dailyLoadPromise=null;reject(Error('The video library did not initialize. Refresh Bloom and try again.'))}};
  script.onerror=()=>{clearTimeout(timeout);script.remove();dailyLoadPromise=null;reject(Error('Could not load the video service. Check your connection and try again.'))};
  document.head.append(script);
 });
 return dailyLoadPromise;
}
if(meetingId){document.querySelector('.prototype').textContent='Meeting invitation';document.querySelector('#joinForm>.fine').textContent=hostKey?'Private host entrance':'No password needed. Your host will admit you from the waiting room.';api('/api/meetings/'+encodeURIComponent(meetingId)).then(meeting=>{document.querySelector('#entrance h1').textContent=meeting.title;document.querySelector('#entrance .intro').textContent='Let’s grow in faith together.'}).catch(error=>setStatus(error.message));
$('joinForm').onsubmit=async e=>{e.preventDefault();const button=$('joinForm').querySelector('[type=submit]');button.disabled=true;joinFeedback.textContent='Connecting to your gathering…';try{const credentials=await api('/api/meetings/'+encodeURIComponent(meetingId)+'/join',{name:$('name').value.trim(),hostKey});const sdk=await loadDaily();const videoWasOn=camOn,audioWasOn=micOn&&!!liveTrack('audio');stopMeter();stream?.getTracks().forEach(t=>t.stop());stream=null;stopShare();sync();let section=$('liveMeeting');if(!section){section=document.createElement('main');section.id='liveMeeting';section.innerHTML='<div class="room-heading"><h2>Together in Bloom</h2><span id="liveRole"></span></div><div id="liveCallFrame"></div><p class="fine">Your gathering has no Bloom time cutoff. Use the call’s device settings, chat, raise hand, and host controls below.</p>';document.body.append(section)}section.hidden=false;$('entrance').hidden=true;$('liveRole').textContent=credentials.isHost?'Host':'Member · Please wait to be admitted';liveCall=sdk.createFrame($('liveCallFrame'),{iframeStyle:{width:'100%',height:'72vh',border:'0',borderRadius:'12px'},showLeaveButton:true});liveCall.on('left-meeting',async()=>{const endedCall=liveCall;liveCall=null;await endedCall.destroy();section.hidden=true;$('entrance').hidden=false;setStatus('You’ve left the gathering.');});liveCall.on('error',event=>{const message=videoErrorMessage(event);setStatus(message);joinFeedback.textContent=message;console.error('Bloom video error: '+message)});liveCall.on('joined-meeting',()=>{$('liveRole').textContent=credentials.isHost?'Host':'Member'});await liveCall.join({url:credentials.url,token:credentials.token,userName:$('name').value.trim(),startVideoOff:!videoWasOn,startAudioOff:!audioWasOn});window.scrollTo(0,0)}catch(error){if(liveCall){await liveCall.destroy().catch(()=>{});liveCall=null}if($('liveMeeting'))$('liveMeeting').hidden=true;$('entrance').hidden=false;const message=videoErrorMessage(error);setStatus(message);joinFeedback.textContent=message;joinFeedback.scrollIntoView({block:'center',behavior:'smooth'});console.error('Bloom join failed: '+message)}finally{button.disabled=false}};
}
